$ErrorActionPreference = 'Stop'
function Quantile([double[]]$values, [double]$percentile) {
    [Array]::Sort($values)
    $position = ($values.Length - 1) * $percentile
    $lower = [int][Math]::Floor($position)
    $upper = [int][Math]::Ceiling($position)
    return $values[$lower] + ($values[$upper] - $values[$lower]) * ($position - $lower)
}
$series = 'handwritten-native-r32'
$directory = Join-Path (Get-Location) "artifacts/ecs-relations/measurements/$series"
$rows = @(foreach ($id in @('default-large-dynamic50-control', 'finite-large-mask1-mutual-control')) {
    $report = Get-Content -Raw -LiteralPath (Join-Path $directory "$id.json") | ConvertFrom-Json
    foreach ($boundary in @('Query','Consume')) {
        foreach ($side in @('H1','H2')) {
            foreach ($position in @('First','Second')) {
                $samples = @($report.RawSamples | Where-Object {
                    $_.Boundary -eq $boundary -and $_.Side -eq $side -and
                    $(if (($_.SideOrder -split '/')[0] -eq $side) { 'First' } else { 'Second' }) -eq $position
                })
                [double[]]$values = @($samples.ElapsedTicks)
                [pscustomobject]@{
                    CaseId=$id; Boundary=$boundary; Side=$side; Position=$position
                    Samples=$values.Length; MedianTicks=(Quantile $values 0.5); P95Ticks=(Quantile $values 0.95)
                    TotalFrameAllocatedBytes=($samples.FrameAllocatedBytes | Measure-Object -Sum).Sum
                    Gen0=($samples.Gen0 | Measure-Object -Sum).Sum
                    Gen1=($samples.Gen1 | Measure-Object -Sum).Sum
                    Gen2=($samples.Gen2 | Measure-Object -Sum).Sum
                    Processors=@($samples.ProcessorBefore + $samples.ProcessorAfter | Select-Object -Unique)
                }
            }
        }
    }
})
$destination = Join-Path (Get-Location) "docs/evidence/ECS-Relations-2026-10-19/$series/handwritten-order.json"
[pscustomobject]@{Series=$series;SourceCommit='3b582fe541d86d7f556b3f9d6854962d292454ef';Required=$false;Quantiles='R7, raw tick precision';Rows=$rows} |
    ConvertTo-Json -Depth 8 | Set-Content -LiteralPath $destination -Encoding utf8
$rows | Format-Table CaseId,Boundary,Side,Position,Samples,MedianTicks,P95Ticks,TotalFrameAllocatedBytes,Gen0,Gen1,Gen2 -AutoSize
Write-Output "ORDER_REPORT $destination"

